 10→/**
 11→ * Central Prometheus metrics registry and collector.
 12→ * Exposes both event-driven counters (incremented by controllers/services)
 13→ * and gauge metrics polled from the database every 30 seconds.
 14→ */
 15→@Injectable()
 16→export class MetricsService implements OnModuleInit {
 17→  private readonly logger = new Logger(MetricsService.name);
 18→  readonly registry: client.Registry;
 19→  private collectInterval: ReturnType<typeof setInterval> | null = null;
 20→
 21→  // --- Gauges (DB-polled state) ---
 22→  readonly usersTotal: client.Gauge;
 23→  readonly filesTotal: client.Gauge;
 24→  readonly storageBytesTotal: client.Gauge;
 25→  readonly ipnsEntriesTotal: client.Gauge;
 26→  readonly republishScheduleTotal: client.Gauge;
 27→
 28→  // --- Counters (event-driven) ---
 29→  readonly fileUploads: client.Counter;
 30→  readonly fileUploadBytes: client.Counter;
 31→  readonly fileDownloads: client.Counter;
 32→  readonly fileUnpins: client.Counter;
 33→  readonly ipnsPublishes: client.Counter;
 34→  readonly ipnsResolves: client.Counter;
 35→  readonly republishRuns: client.Counter;
 36→  readonly republishEntriesProcessed: client.Counter;
 37→  readonly authLogins: client.Counter;
 38→
 39→  // --- Counters (delegated routing) ---
 40→  readonly delegatedRoutingRequests: client.Counter;
 41→  readonly delegatedRoutingFallbacks: client.Counter;
 42→
 43→  // --- Histograms ---
 44→  readonly httpRequestDuration: client.Histogram;
 45→  readonly ipfsIpnsDuration: client.Histogram;
 46→  readonly republishBatchDuration: client.Histogram;
 47→  readonly ipnsResolveDuration: client.Histogram;
 48→  readonly ipnsPublishDuration: client.Histogram;
 49→
 50→  constructor(
 51→    @InjectRepository(PinnedCid)
 52→    private readonly pinnedCidRepository: Repository<PinnedCid>,
 53→    @InjectRepository(FolderIpns)
 54→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 55→    @InjectRepository(User)
 56→    private readonly userRepository: Repository<User>,
 57→    @InjectRepository(IpnsRepublishSchedule)
 58→    private readonly republishScheduleRepository: Repository<IpnsRepublishSchedule>
 59→  ) {
 60→    this.registry = new client.Registry();
 61→    this.registry.setDefaultLabels({ app: 'cipherbox-api' });
 62→
 63→    // Gauges
 64→    this.usersTotal = new client.Gauge({
 65→      name: 'cipherbox_users_total',
 66→      help: 'Total registered users',
 67→      registers: [this.registry],
 68→    });
 69→
 70→    this.filesTotal = new client.Gauge({
 71→      name: 'cipherbox_files_total',
 72→      help: 'Total pinned files across all users',
 73→      registers: [this.registry],
 74→    });
 75→
 76→    this.storageBytesTotal = new client.Gauge({
 77→      name: 'cipherbox_storage_bytes_total',
 78→      help: 'Total storage used across all users in bytes',
 79→      registers: [this.registry],
 80→    });
 81→
 82→    this.ipnsEntriesTotal = new client.Gauge({
 83→      name: 'cipherbox_ipns_entries_total',
 84→      help: 'Total IPNS entries by record type',
 85→      labelNames: ['record_type'],
 86→      registers: [this.registry],
 87→    });
 88→
 89→    this.republishScheduleTotal = new client.Gauge({
 90→      name: 'cipherbox_republish_schedule_total',
 91→      help: 'IPNS republish schedule entries by status',
 92→      labelNames: ['status'],
 93→      registers: [this.registry],
 94→    });
 95→
 96→    // Counters
 97→    this.fileUploads = new client.Counter({
 98→      name: 'cipherbox_file_uploads_total',
 99→      help: 'Total file uploads',
100→      registers: [this.registry],
101→    });
102→
103→    this.fileUploadBytes = new client.Counter({
104→      name: 'cipherbox_file_upload_bytes_total',
105→      help: 'Total bytes uploaded',
106→      registers: [this.registry],
107→    });
108→
109→    this.fileDownloads = new client.Counter({
110→      name: 'cipherbox_file_downloads_total',
111→      help: 'Total file downloads',
112→      registers: [this.registry],
113→    });
114→
115→    this.fileUnpins = new client.Counter({
116→      name: 'cipherbox_file_unpins_total',
117→      help: 'Total file unpins',
118→      registers: [this.registry],
119→    });
120→
121→    this.ipnsPublishes = new client.Counter({
122→      name: 'cipherbox_ipns_publishes_total',
123→      help: 'Total IPNS publishes',
124→      labelNames: ['type'],
125→      registers: [this.registry],
126→    });
127→
128→    this.ipnsResolves = new client.Counter({
129→      name: 'cipherbox_ipns_resolves_total',
130→      help: 'Total IPNS resolves',
131→      labelNames: ['source'],
132→      registers: [this.registry],
133→    });
134→
135→    this.republishRuns = new client.Counter({
