175→      buckets: [0.01, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10],
176→      registers: [this.registry],
177→    });
178→
179→    this.ipfsIpnsDuration = new client.Histogram({
180→      name: 'cipherbox_ipfs_ipns_duration_seconds',
181→      help: 'Duration of IPFS/IPNS operations in seconds',
182→      labelNames: ['operation', 'result', 'source'] as const,
183→      buckets: [0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10, 20, 30],
184→      registers: [this.registry],
