  1→import type { PinningProvider, PinResult, PinStatus } from './types';
  2→
  3→/** Timeout for all Kubo RPC requests (30 seconds) */
  4→const REQUEST_TIMEOUT_MS = 30_000;
  5→
  6→/**
  7→ * PinningProvider implementation for Kubo RPC API (/api/v0/*).
  8→ *
  9→ * Talks directly to a Kubo node's HTTP API. Suitable for self-hosted
 10→ * Kubo nodes or any IPFS node exposing the Kubo-compatible RPC interface.
 11→ */
 12→export class KuboProvider implements PinningProvider {
 13→  private readonly endpoint: string;
 14→  private readonly authToken?: string;
 15→
 16→  constructor(endpoint: string, authToken?: string) {
 17→    // Normalize: strip trailing slash
 18→    this.endpoint = endpoint.replace(/\/+$/, '');
 19→    this.authToken = authToken;
 20→  }
 21→
 22→  /**
 23→   * Upload and pin data to the Kubo node.
 24→   * Uses /api/v0/add with pin=true and cid-version=1 for CIDv1.
 25→   */
 26→  async pin(data: Uint8Array, _name?: string): Promise<PinResult> {
 27→    const url = `${this.endpoint}/api/v0/add?pin=true&cid-version=1`;
 28→    const formData = new FormData();
 29→    // Pass typed array directly to Blob (never use .buffer to avoid offset issues)
 30→    const blob = new Blob([data as BlobPart], { type: 'application/octet-stream' });
 31→    formData.append('file', blob);
 32→
 33→    const response = await fetch(url, {
 34→      method: 'POST',
 35→      body: formData,
 36→      headers: this.buildHeaders(),
 37→      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
 38→    });
 39→
 40→    if (!response.ok) {
 41→      const errorText = await response.text();
 42→      throw new Error(`Kubo add failed: ${response.status} - ${errorText}`);
 43→    }
 44→
 45→    // Kubo returns ndjson; for a single file, parse the first (only) line
 46→    const text = await response.text();
 47→    const result = JSON.parse(text) as { Hash: string; Size: string };
 48→    return {
 49→      cid: result.Hash,
 50→      size: parseInt(result.Size, 10),
 51→    };
 52→  }
 53→
 54→  /**
 55→   * Remove a pin by CID.
 56→   * Ignores "not pinned" errors for idempotency.
 57→   */
 58→  async unpin(cid: string): Promise<void> {
 59→    const url = `${this.endpoint}/api/v0/pin/rm?arg=${encodeURIComponent(cid)}`;
 60→
 61→    const response = await fetch(url, {
 62→      method: 'POST',
 63→      headers: this.buildHeaders(),
 64→      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
 65→    });
 66→
 67→    if (!response.ok) {
 68→      const errorText = await response.text();
 69→      // "not pinned" means already unpinned -- treat as success (idempotent)
 70→      if (errorText.toLowerCase().includes('not pinned')) {
 71→        return;
 72→      }
 73→      throw new Error(`Kubo unpin failed: ${response.status} - ${errorText}`);
 74→    }
 75→  }
 76→
 77→  /**
 78→   * Check pin status by CID.
 79→   * Returns 'pinned' on success, 'failed' if the CID is not pinned.
 80→   */
 81→  async status(cid: string): Promise<PinStatus> {
 82→    const url = `${this.endpoint}/api/v0/pin/ls?arg=${encodeURIComponent(cid)}`;
 83→
 84→    try {
 85→      const response = await fetch(url, {
 86→        method: 'POST',
 87→        headers: this.buildHeaders(),
 88→        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
 89→      });
 90→
 91→      if (!response.ok) {
 92→        return { cid, status: 'failed' };
 93→      }
 94→
 95→      return { cid, status: 'pinned' };
 96→    } catch {
 97→      return { cid, status: 'failed' };
 98→    }
 99→  }
100→
101→  /**
102→   * Fetch pinned content by CID.
103→   * Returns the raw bytes of the content.
104→   */
105→  async get(cid: string): Promise<Uint8Array> {
106→    const url = `${this.endpoint}/api/v0/cat?arg=${encodeURIComponent(cid)}`;
107→
108→    const response = await fetch(url, {
109→      method: 'POST',
110→      headers: this.buildHeaders(),
111→      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
112→    });
113→
114→    if (!response.ok) {
115→      const errorText = await response.text();
116→      throw new Error(`Kubo cat failed: ${response.status} - ${errorText}`);
117→    }
118→
119→    return new Uint8Array(await response.arrayBuffer());
120→  }
121→
122→  /** Build auth headers for Kubo requests */
123→  private buildHeaders(): Record<string, string> {
124→    if (this.authToken) {
125→      return { Authorization: `Basic ${this.authToken}` };
126→    }
127→    return {};
128→  }
129→}
