  1→import type { PinningProvider, PinResult, PinStatus } from './types';
  2→
  3→/** Timeout for all PSA requests (30 seconds) */
  4→const REQUEST_TIMEOUT_MS = 30_000;
  5→
  6→/** PSA pin object from the Pinning Service API response */
  7→interface PsaPinObject {
  8→  requestid: string;
  9→  status: 'queued' | 'pinning' | 'pinned' | 'failed';
 10→  pin: {
 11→    cid: string;
 12→    name?: string;
 13→  };
 14→}
 15→
 16→/** PSA list response */
 17→interface PsaListResponse {
 18→  count: number;
 19→  results: PsaPinObject[];
 20→}
 21→
 22→/**
 23→ * PinningProvider implementation for the IPFS Pinning Service API (PSA).
 24→ *
 25→ * PSA is a CID-reference-only protocol: it cannot accept raw data uploads.
 26→ * Data must be uploaded to an IPFS node first, then the CID is submitted
 27→ * to the pinning service for retrieval and pinning.
 28→ *
 29→ * Supports: Pinata, web3.storage, Filebase, and any PSA-compatible service.
 30→ */
 31→export class PsaProvider implements PinningProvider {
 32→  private readonly endpoint: string;
 33→  private readonly authToken: string;
 34→
 35→  constructor(endpoint: string, authToken: string) {
 36→    // Normalize: strip trailing slash
 37→    this.endpoint = endpoint.replace(/\/+$/, '');
 38→    this.authToken = authToken;
 39→  }
 40→
 41→  /**
 42→   * PSA cannot upload raw data. Always throws.
 43→   * Use pinByCid() after uploading via CipherBox relay or a Kubo node.
 44→   */
 45→  async pin(_data: Uint8Array, _name?: string): Promise<PinResult> {
 46→    throw new Error(
 47→      'PsaProvider.pin() cannot upload raw data. Use pinByCid() after uploading via CipherBox relay or Kubo node.'
 48→    );
 49→  }
 50→
 51→  /**
 52→   * Pin a CID on the pinning service.
 53→   * The service will retrieve the content from the IPFS network and pin it.
 54→   */
 55→  async pinByCid(
 56→    cid: string,
 57→    name?: string
 58→  ): Promise<{ cid: string; status: PinStatus['status'] }> {
 59→    const url = `${this.endpoint}/pins`;
 60→    const body = {
 61→      cid,
 62→      name: name ?? `cipherbox-${Date.now()}`,
 63→    };
 64→
 65→    const response = await fetch(url, {
 66→      method: 'POST',
 67→      headers: this.buildHeaders({ 'Content-Type': 'application/json' }),
 68→      body: JSON.stringify(body),
 69→      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
 70→    });
 71→
 72→    if (!response.ok) {
 73→      const errorText = await response.text();
 74→      throw new Error(`PSA pin failed: ${response.status} - ${errorText}`);
 75→    }
 76→
 77→    const result = (await response.json()) as PsaPinObject;
 78→    return {
 79→      cid: result.pin.cid,
 80→      status: result.status,
 81→    };
 82→  }
 83→
 84→  /**
 85→   * Remove a pin by CID.
 86→   * PSA uses requestid for deletion, so we first list pins by CID
 87→   * to find the requestid(s), then delete each one.
 88→   */
 89→  async unpin(cid: string): Promise<void> {
 90→    // First, find the pin request(s) for this CID
 91→    const listUrl = `${this.endpoint}/pins?cid=${encodeURIComponent(cid)}&status=pinned,pinning,queued`;
 92→
 93→    const listResponse = await fetch(listUrl, {
 94→      method: 'GET',
 95→      headers: this.buildHeaders(),
 96→      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
 97→    });
 98→
 99→    if (!listResponse.ok) {
100→      const errorText = await listResponse.text();
101→      throw new Error(`PSA list for unpin failed: ${listResponse.status} - ${errorText}`);
102→    }
103→
104→    const listResult = (await listResponse.json()) as PsaListResponse;
105→
106→    // Delete each pin request by its requestid
107→    for (const pin of listResult.results) {
108→      const deleteUrl = `${this.endpoint}/pins/${encodeURIComponent(pin.requestid)}`;
109→
110→      const deleteResponse = await fetch(deleteUrl, {
111→        method: 'DELETE',
112→        headers: this.buildHeaders(),
113→        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
114→      });
115→
116→      if (!deleteResponse.ok) {
117→        const errorText = await deleteResponse.text();
118→        throw new Error(
119→          `PSA delete pin ${pin.requestid} failed: ${deleteResponse.status} - ${errorText}`
120→        );
121→      }
122→    }
123→  }
124→
125→  /**
126→   * Check pin status by CID.
127→   * Queries the pinning service for the latest status of a CID.
128→   */
129→  async status(cid: string): Promise<PinStatus> {
130→    const url = `${this.endpoint}/pins?cid=${encodeURIComponent(cid)}&limit=1`;
131→
132→    const response = await fetch(url, {
133→      method: 'GET',
134→      headers: this.buildHeaders(),
135→      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
136→    });
137→
138→    if (!response.ok) {
139→      return { cid, status: 'failed' };
140→    }
141→
142→    const result = (await response.json()) as PsaListResponse;
143→
144→    if (result.count === 0 || result.results.length === 0) {
145→      return { cid, status: 'failed' };
146→    }
147→
148→    return {
149→      cid,
150→      status: result.results[0].status,
151→    };
152→  }
153→
154→  /**
155→   * PSA does not support content retrieval. Always throws.
156→   * Use an IPFS gateway to fetch content by CID.
157→   */
158→  async get(_cid: string): Promise<Uint8Array> {
159→    throw new Error('PsaProvider does not support content retrieval. Use an IPFS gateway.');
160→  }
161→
162→  /** Build auth headers with Bearer token */
163→  private buildHeaders(extra?: Record<string, string>): Record<string, string> {
164→    return {
165→      Authorization: `Bearer ${this.authToken}`,
166→      ...extra,
167→    };
168→  }
169→}
