  1→import type { ConnectionTestResult } from './types';
  2→
  3→/** Timeout for each connection probe (10 seconds) */
  4→const PROBE_TIMEOUT_MS = 10_000;
  5→
  6→/**
  7→ * Test connection to an IPFS endpoint and auto-detect the protocol.
  8→ *
  9→ * Sequential probe strategy:
 10→ * 1. Try Kubo RPC: POST /api/v0/id (skipped if endpoint contains pinata.cloud)
 11→ * 2. Try Pinata: GET /data/testAuthentication
 12→ * 3. Try PSA: GET /pins?limit=1
 13→ *
 14→ * Detects CORS errors and provides protocol-specific remediation instructions.
 15→ */
 16→export async function testConnection(
 17→  endpoint: string,
 18→  authToken?: string
 19→): Promise<ConnectionTestResult> {
 20→  const normalizedEndpoint = endpoint.replace(/\/+$/, '');
 21→  const isPinataUrl = normalizedEndpoint.toLowerCase().includes('pinata.cloud');
 22→
 23→  if (isPinataUrl) {
 24→    // Pinata URL detected -- try Pinata probe first (skip Kubo)
 25→    const pinataResult = await probePinata(normalizedEndpoint, authToken);
 26→    if (pinataResult) return pinataResult;
 27→  } else {
 28→    // --- Probe 1: Kubo RPC ---
 29→    const kuboResult = await probeKubo(normalizedEndpoint, authToken);
 30→    if (kuboResult) return kuboResult;
 31→
 32→    // --- Probe 2: Pinata ---
 33→    const pinataResult = await probePinata(normalizedEndpoint, authToken);
 34→    if (pinataResult) return pinataResult;
 35→  }
 36→
 37→  // --- Probe 3: PSA ---
 38→  const psaResult = await probePsa(normalizedEndpoint, authToken);
 39→  if (psaResult) return psaResult;
 40→
 41→  // No protocol detected
 42→  return {
 43→    success: false,
 44→    latencyMs: 0,
 45→    error: 'could not detect ipfs protocol at this endpoint.',
 46→  };
 47→}
 48→
 49→/** Probe Kubo RPC endpoint via POST /api/v0/id */
 50→async function probeKubo(
 51→  endpoint: string,
 52→  authToken?: string
 53→): Promise<ConnectionTestResult | null> {
 54→  const url = `${endpoint}/api/v0/id`;
 55→  const headers: Record<string, string> = {};
 56→  if (authToken) {
 57→    headers['Authorization'] = `Basic ${authToken}`;
 58→  }
 59→
 60→  const start = performance.now();
 61→
 62→  try {
 63→    const response = await fetch(url, {
 64→      method: 'POST',
 65→      headers,
 66→      signal: AbortSignal.timeout(PROBE_TIMEOUT_MS),
 67→    });
 68→
 69→    const latencyMs = Math.round(performance.now() - start);
 70→
 71→    if (response.ok) {
 72→      const data = (await response.json()) as { AgentVersion?: string };
 73→      return {
 74→        success: true,
 75→        protocol: 'kubo',
 76→        version: data.AgentVersion,
 77→        latencyMs,
 78→      };
 79→    }
 80→
 81→    // 401/403/422 means the endpoint exists and speaks Kubo, but auth failed
 82→    if (response.status === 401 || response.status === 403 || response.status === 422) {
 83→      return {
 84→        success: false,
 85→        protocol: 'kubo',
 86→        latencyMs,
 87→        error: 'authentication failed. check your auth token.',
 88→      };
 89→    }
 90→
 91→    // Other non-200 -- not Kubo, try PSA
 92→    return null;
 93→  } catch (err) {
 94→    const latencyMs = Math.round(performance.now() - start);
 95→
 96→    if (isCorsError(err)) {
 97→      return {
 98→        success: false,
 99→        latencyMs,
100→        corsError: true,
101→        corsInstructions: kuboCorsInstructions(endpoint),
102→        error: 'CORS error: browser blocked the request. configure cors on your kubo node.',
103→      };
104→    }
105→
106→    if (isTimeoutError(err)) {
107→      return {
108→        success: false,
109→        latencyMs,
110→        error: 'connection timed out after 10 seconds.',
111→      };
112→    }
113→
114→    // Other errors (e.g., DNS failure, network down) -- try PSA
115→    return null;
116→  }
117→}
118→
119→/** Probe Pinata API via GET /data/testAuthentication */
120→async function probePinata(
121→  endpoint: string,
122→  authToken?: string
123→): Promise<ConnectionTestResult | null> {
124→  const url = `${endpoint}/data/testAuthentication`;
125→  const headers: Record<string, string> = {};
126→  if (authToken) {
127→    headers['Authorization'] = `Bearer ${authToken}`;
128→  }
129→
130→  const start = performance.now();
131→
132→  try {
133→    const response = await fetch(url, {
134→      method: 'GET',
135→      headers,
136→      signal: AbortSignal.timeout(PROBE_TIMEOUT_MS),
137→    });
138→
139→    const latencyMs = Math.round(performance.now() - start);
140→
141→    if (response.ok) {
142→      return {
143→        success: true,
144→        protocol: 'pinata',
145→        version: 'Pinata API v3',
146→        latencyMs,
147→      };
148→    }
149→
150→    if (response.status === 401 || response.status === 403) {
151→      return {
152→        success: false,
153→        protocol: 'pinata',
154→        latencyMs,
155→        error: 'authentication failed. check your pinata jwt token.',
156→      };
157→    }
158→
159→    return null;
160→  } catch (err) {
161→    const latencyMs = Math.round(performance.now() - start);
162→
163→    if (isCorsError(err)) {
164→      return {
165→        success: false,
166→        latencyMs,
167→        corsError: true,
168→        corsInstructions:
169→          'pinata api should support browser requests. check if your jwt token has the correct permissions.',
170→        error: 'CORS error when connecting to pinata.',
171→      };
172→    }
173→
174→    return null;
175→  }
176→}
177→
178→/** Probe PSA endpoint via GET /pins?limit=1 */
179→async function probePsa(
180→  endpoint: string,
181→  authToken?: string
182→): Promise<ConnectionTestResult | null> {
183→  const url = `${endpoint}/pins?limit=1`;
184→  const headers: Record<string, string> = {};
185→  if (authToken) {
186→    headers['Authorization'] = `Bearer ${authToken}`;
187→  }
188→
189→  const start = performance.now();
190→
191→  try {
192→    const response = await fetch(url, {
193→      method: 'GET',
194→      headers,
195→      signal: AbortSignal.timeout(PROBE_TIMEOUT_MS),
196→    });
197→
198→    const latencyMs = Math.round(performance.now() - start);
199→
200→    if (response.ok) {
201→      return {
202→        success: true,
203→        protocol: 'psa',
204→        latencyMs,
205→      };
206→    }
207→
208→    if (response.status === 401 || response.status === 403 || response.status === 422) {
209→      return {
210→        success: false,
211→        protocol: 'psa',
212→        latencyMs,
213→        error: 'authentication failed. check your auth token.',
214→      };
215→    }
216→
217→    // Other non-200 status -- not recognizable as PSA
218→    return null;
219→  } catch (err) {
220→    const latencyMs = Math.round(performance.now() - start);
221→
222→    if (isCorsError(err)) {
223→      return {
224→        success: false,
225→        latencyMs,
226→        corsError: true,
227→        corsInstructions: psaCorsInstructions(),
228→        error: 'CORS error: browser blocked the request. check your pinning service cors settings.',
229→      };
230→    }
231→
232→    if (isTimeoutError(err)) {
233→      return {
234→        success: false,
235→        latencyMs,
236→        error: 'connection timed out after 10 seconds.',
237→      };
238→    }
239→
240→    // Other errors
241→    return null;
242→  }
243→}
244→
245→/**
246→ * Detect CORS errors from fetch.
247→ * Browsers throw TypeError with specific messages when CORS blocks a request.
248→ */
249→function isCorsError(err: unknown): boolean {
250→  if (!(err instanceof TypeError)) return false;
251→  const message = err.message.toLowerCase();
252→  return (
253→    message.includes('failed to fetch') ||
254→    message.includes('networkerror') ||
255→    message.includes('network request failed')
256→  );
257→}
258→
259→/** Detect AbortSignal timeout errors */
260→function isTimeoutError(err: unknown): boolean {
261→  return err instanceof DOMException && err.name === 'AbortError';
262→}
263→
264→/** CORS configuration instructions for Kubo nodes */
265→function kuboCorsInstructions(endpoint: string): string {
266→  void endpoint; // endpoint available for future per-node instructions
267→  return [
268→    'Configure CORS on your Kubo node:',
269→    '',
270→    `ipfs config --json API.HTTPHeaders.Access-Control-Allow-Origin '["https://app.cipherbox.cc", "http://localhost:5173"]'`,
271→    `ipfs config --json API.HTTPHeaders.Access-Control-Allow-Methods '["POST"]'`,
272→    `ipfs config --json API.HTTPHeaders.Access-Control-Allow-Headers '["Authorization", "Content-Type"]'`,
273→    '',
274→    'Then restart your Kubo node.',
275→  ].join('\n');
276→}
277→
278→/** CORS configuration instructions for PSA services */
279→function psaCorsInstructions(): string {
280→  return 'check your pinning service dashboard for cors/allowed-origins settings. add https://app.cipherbox.cc to the allowed origins list.';
281→}
282→

